import sys
MOD = 10**9 + 7

def solve():
    input = sys.stdin.read().split()
    n = int(input[0])
    words = input[1:n+1]

    def get_candidates(word):
        candidates = set()
        for i in range(len(word)):
            candidate = word[:i] + word[i+1:]
            candidates.add(candidate)
        candidates.add(word)  # option to not remove any character
        return candidates

    # Precompute all possible candidates for each word
    candidates_list = []
    for word in words:
        candidates = get_candidates(word)
        candidates_list.append(candidates)

    # DP[i][j] = number of ways to choose first i words with j-th candidate of i-th word
    # Initialize DP
    dp_prev = {}
    for j, candidate in enumerate(candidates_list[0]):
        dp_prev[candidate] = 1

